//! Rust types for the Conn client contract (`packages/contracts`), generated by
//! `tools/gen-contract.mjs`. Do not edit `src/generated.rs`; regenerate it.
//!
//! - Every schema a client sends or receives has a type under its contract name, such as
//!   [`OrchestrationV2Command`]. The short names the other tracks used for placeholders
//!   ([`Command`], [`ShellStreamItem`], ...) are aliases of those.
//! - [`rpc`] gives each method's `Payload`, `Success` or `Item`, and `Error`, by tag:
//!   `rpc::orchestration::dispatch_command::Payload`.
//! - [`methods`] lists every RPC method a client can call, from `methods.json`.
//! - [`ids`] holds branded string ids. Effect 4 brands exist only in TypeScript types, so the
//!   generated fields are plain `String`; convert with `ThreadId::from(s)` / `String::from(id)`.
//! - [`support`] holds the hand-written pieces the generated code uses.
//! - [`T3_SERVER_VERSION`] is the T3 server version at the pin (`src/upstream.rs`, generated by
//!   `tools/gen-upstream.mjs` in this repository).
//!
//! Each type encodes to the JSON the TypeScript server sends (`Schema.toCodecJson`), and decodes
//! what it accepts. Checks such as `maxLength` or `pattern` are not enforced.

use std::sync::OnceLock;

use serde::{Deserialize, Serialize, de::DeserializeOwned};
use serde_json::Value;

mod generated;
pub mod ids;
pub mod support;
mod upstream;

pub use generated::*;
pub use ids::*;
pub use upstream::{
    PROVIDER_SEND_TURN_MAX_FILE_BYTES, T3_SERVER_VERSION, THREAD_TRANSCRIPT_HEADER_PARTS,
};

/// `ORCHESTRATION_PROTOCOL_VERSION` in `packages/contracts/src/environment.ts`. `/ws` answers
/// 426 unless the `orchestrationProtocol` query param equals it.
pub const ORCHESTRATION_PROTOCOL_VERSION: u32 = 2;
pub const ORCHESTRATION_PROTOCOL_QUERY_PARAM: &str = "orchestrationProtocol";

/// One RPC method of the client contract.
#[derive(Clone, Debug, Deserialize)]
pub struct MethodInfo {
    /// The Effect RPC tag, such as `orchestration.dispatchCommand`.
    pub tag: String,
    /// True when the success schema is an `RpcSchema.Stream`.
    pub stream: bool,
    /// `official` (upstream T3) or `fork` (Conn-only).
    pub origin: String,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct MethodsFile {
    contract_digest: String,
    methods: Vec<MethodInfo>,
}

fn methods_file() -> &'static MethodsFile {
    static FILE: OnceLock<MethodsFile> = OnceLock::new();
    FILE.get_or_init(|| {
        serde_json::from_str(include_str!("../methods.json")).expect("methods.json is valid")
    })
}

/// Every method in the client contract, sorted by tag.
pub fn methods() -> &'static [MethodInfo] {
    &methods_file().methods
}

/// The sha256 of the contract inputs (`packages/contracts` and T3's `ProviderAdapter.ts`) the
/// files were generated from, by path; `gen-contract.mjs --check` fails when the tree moved.
pub fn contract_digest() -> &'static str {
    &methods_file().contract_digest
}

pub fn method(tag: &str) -> Option<&'static MethodInfo> {
    let all = methods();
    all.binary_search_by(|m| m.tag.as_str().cmp(tag))
        .ok()
        .map(|i| &all[i])
}

/// Builds a contract value from JSON in its wire shape.
pub fn from_json<T: DeserializeOwned>(value: Value) -> Result<T, serde_json::Error> {
    serde_json::from_value(value)
}

/// Encodes a contract value to its wire shape.
pub fn to_json<T: Serialize>(value: &T) -> Value {
    serde_json::to_value(value).expect("contract values always serialize")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn method_list_matches_the_contract() {
        let all = methods();
        // methods.json is generated; the counts move with each pin. A fixed count failed every
        // bump that added a method, so only check that the file holds a real method list.
        assert!(all.len() > 200, "methods.json lists {} methods", all.len());
        assert!(
            all.iter().filter(|m| m.stream).count() > 20,
            "methods.json lists too few streams"
        );
        assert!(
            all.windows(2).all(|w| w[0].tag < w[1].tag),
            "sorted, unique"
        );
        assert!(method("orchestration.subscribeShell").unwrap().stream);
        assert!(!method("orchestration.dispatchCommand").unwrap().stream);
        assert!(method("nope").is_none());
        assert_eq!(contract_digest().len(), 64);
    }

    #[test]
    fn placeholders_round_trip_wire_json() {
        let json = serde_json::json!({"type":"thread.stop","commandId":"c1","threadId":"t1"});
        let command: Command = from_json(json.clone()).unwrap();
        assert_eq!(to_json(&command), json);
        let thread: ThreadId = from_json(serde_json::json!("t1")).unwrap();
        assert_eq!(thread.as_str(), "t1");
    }

    /// `gen-contract.mjs` writes a redacting `Debug` for every field the contract marks as a
    /// secret (`isSecretSetting`), a `Redacted` value, and a field named `secret`.
    #[test]
    fn secret_fields_never_show_in_debug() {
        const SECRET: &str = "s3cr3t-value";
        let signature: ScheduledTaskUpsertScheduleWebhookSignature = from_json(serde_json::json!({
            "header": "x-hub-signature-256", "encoding": "hex", "prefix": "sha256=",
            "secret": SECRET,
        }))
        .unwrap();
        let answer: SecretRequestAnswerInputAnswerSave =
            from_json(serde_json::json!({"type": "save", "secret": SECRET})).unwrap();
        let generator: TextGeneratorConfig = from_json(serde_json::json!({
            "kind": "openaiCompatible", "baseUrl": "https://api.example.com/v1", "apiKey": SECRET,
        }))
        .unwrap();
        let ticket: AuthWebSocketTicketResult = from_json(
            serde_json::json!({"ticket": SECRET, "expiresAt": "2026-01-01T00:00:00.000Z"}),
        )
        .unwrap();
        for shown in [
            format!("{signature:?}"),
            format!("{answer:?}"),
            format!("{generator:?}"),
            format!("{ticket:?}"),
            format!("{signature:#?}"),
        ] {
            assert!(!shown.contains(SECRET), "{shown}");
            assert!(shown.contains("<redacted>"), "{shown}");
        }
        // The other fields still show, and the wire keeps the value.
        assert!(format!("{signature:?}").contains("x-hub-signature-256"));
        assert_eq!(to_json(&answer)["secret"], SECRET);
    }
}
